import{_ as o,C as n,o as r,c as s,j as e,a as i,G as l,a3 as d}from"./chunks/framework.Bvm_liKL.js";const f=JSON.parse('{"title":"Installation & Update Channels","description":"System requirements, installer vs portable, and what each update channel means","frontmatter":{"title":"Installation & Update Channels","description":"System requirements, installer vs portable, and what each update channel means"},"headers":[],"relativePath":"en/guide/installation.md","filePath":"en/guide/installation.md"}'),c={name:"en/guide/installation.md"};function h(u,t,p,m,b,g){const a=n("ArticleMetadata");return r(),s("div",null,[t[0]||(t[0]=e("h1",{id:"installation-update-channels",tabindex:"-1"},[i("Installation & Update Channels "),e("a",{class:"header-anchor",href:"#installation-update-channels","aria-label":'Permalink to "Installation & Update Channels"'},"​")],-1)),l(a),t[1]||(t[1]=d('<h2 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Requirement</th></tr></thead><tbody><tr><td>OS</td><td>Windows 10 1809 (build 17763) or later, Windows 11</td></tr><tr><td>Runtime</td><td><strong>.NET 6 Desktop Runtime</strong> (<code>net6.0-windows10.0.19041.0</code>)</td></tr><tr><td>Memory</td><td>4GB or more recommended</td></tr><tr><td>GPU</td><td>A Direct3D 11 capable GPU enables hardware-accelerated ink rendering</td></tr><tr><td>Input</td><td>Touch screen, pen tablet or mouse; touch devices give the best experience</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">About the .NET version</p><p>The main application runs on <strong>.NET 6</strong>, not .NET Framework 4.x. The installer prompts for the runtime when needed. If the portable build won&#39;t start, you are most likely missing the .NET 6 Desktop Runtime — download &quot;.NET Desktop Runtime 6.x&quot; (x64 or x86) from Microsoft.</p><p>Exception: the IACore component used for handwriting recognition is 32-bit only, so the app spawns a small .NET Framework 4.7.2 helper process to talk to it. The installer handles this; no manual action is normally required.</p></div><h2 id="installer-or-portable" tabindex="-1">Installer or portable <a class="header-anchor" href="#installer-or-portable" aria-label="Permalink to &quot;Installer or portable&quot;">​</a></h2><p>Both forms are published for every release and are functionally identical:</p><table tabindex="0"><thead><tr><th></th><th>Installer (<code>.exe</code>)</th><th>Portable (<code>.zip</code>)</th></tr></thead><tbody><tr><td>Setup</td><td>Run the install wizard</td><td>Extract anywhere</td></tr><tr><td>Start menu / desktop shortcuts</td><td>Created automatically</td><td>Create manually</td></tr><tr><td>Uninstall</td><td>Via Windows Settings</td><td>Delete the folder</td></tr><tr><td>Writes to the system</td><td>Yes (install dir, uninstall registry entry)</td><td>No</td></tr><tr><td>Best for</td><td>Personal PCs, long-term use</td><td>USB sticks, lab deployments, multiple versions side by side</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Recommendation</p><p>Use the <strong>installer</strong> on classroom PCs that stay put. Use the <strong>portable</strong> build when you need to carry it between machines or keep several versions at once.</p></div><h2 id="_32-bit-or-64-bit" tabindex="-1">32-bit or 64-bit <a class="header-anchor" href="#_32-bit-or-64-bit" aria-label="Permalink to &quot;32-bit or 64-bit&quot;">​</a></h2><ul><li>On any modern device, pick <strong>64-bit (x64)</strong></li><li>Pick <strong>32-bit (x86)</strong> only if your OS is 32-bit, or you need tight integration with 32-bit Office</li></ul><p>Press <kbd>Win</kbd> + <kbd>Pause</kbd> and check &quot;System type&quot; if you are unsure.</p><h2 id="the-four-channels" tabindex="-1">The four channels <a class="header-anchor" href="#the-four-channels" aria-label="Permalink to &quot;The four channels&quot;">​</a></h2><p>The channel switcher on the download page maps to four different build sources:</p><table tabindex="0"><thead><tr><th>Channel</th><th>Source</th><th>Includes pre-releases</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Beta</strong> (recommended)</td><td><code>community-beta</code> repo</td><td>✅</td><td>Fastest updates and fixes; best choice for daily use</td></tr><tr><td><strong>Preview</strong></td><td><code>community-beta</code> repo</td><td>❌</td><td>More conservative than Beta</td></tr><tr><td><strong>Stable</strong></td><td><code>community</code> main repo</td><td>❌</td><td>Lowest release frequency; maximum stability</td></tr><tr><td><strong>Nightly</strong></td><td>GitHub Actions artifacts</td><td>—</td><td><strong>Untested Debug builds</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Nightly builds</p><p>Nightly is a <strong>Debug</strong> build produced automatically by CI from the latest commit on the <code>net6</code> branch. It is completely untested and may contain severe defects, crashes or risk of data loss. <strong>Do not use it in a real classroom.</strong> The download page forces you to read the warning and tick a confirmation box before the download is allowed.</p></div><h3 id="why-beta-installers-come-from-the-main-repository" tabindex="-1">Why Beta installers come from the main repository <a class="header-anchor" href="#why-beta-installers-come-from-the-main-repository" aria-label="Permalink to &quot;Why Beta installers come from the main repository&quot;">​</a></h3><p>The <code>community-beta</code> repository only publishes portable zip files. When the download page finds no installer on that channel, it falls back to the main <code>community</code> repository using the <strong>same version tag</strong> and marks the button with &quot;Main repo&quot;. The versions match, so it is safe to use.</p><h2 id="download-acceleration" tabindex="-1">Download acceleration <a class="header-anchor" href="#download-acceleration" aria-label="Permalink to &quot;Download acceleration&quot;">​</a></h2><p>On load, the download page probes two kinds of routes in parallel and shows the result at the top:</p><ul><li><strong>Smart-Teach mirror</strong>: good direct-connect speed in mainland China, portable zip only. Before the download actually starts, the page re-checks that the file exists and silently falls back if it doesn&#39;t</li><li><strong>GitHub proxies</strong>: six candidate nodes race each other; the fastest one serves installers and API requests. If none respond, it falls back to a direct GitHub connection</li></ul><p>Nightly artifacts are hosted on <code>nightly.link</code> and can only use the proxy nodes listed on the page. You can switch nodes manually and your choice is remembered.</p><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><p>ICC-CE has a built-in update check; the frequency and channel are configurable in settings. To upgrade manually:</p><ul><li><strong>Installer</strong>: just run the new installer over the old version; settings and ink are preserved</li><li><strong>Portable</strong>: extract the new version into a new folder, then copy your settings file and the <code>Saves</code> folder over from the old one</li></ul><p>See <a href="/website/en/guide/files-and-data">Files &amp; Data Locations</a> for exact paths.</p><div class="warning custom-block"><p class="custom-block-title">Switching channels</p><p>Downgrading from Beta to Stable may leave settings keys that the older build doesn&#39;t understand. If you hit strange behaviour, back up and delete the settings file so it regenerates.</p></div><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><ul><li><strong>Installer</strong>: Settings → Apps → Installed apps → InkCanvasForClass CE → Uninstall</li><li><strong>Portable</strong>: delete the folder</li></ul><p>Uninstalling does not remove your settings or saved ink. Delete the data directory manually for a clean wipe.</p>',28))])}const k=o(c,[["render",h]]);export{f as __pageData,k as default};
